import sys


def solve(text):
    rows = [r.rstrip('\r') for r in text.split('\n') if r.strip() != '']
    if not rows:
        return -1
    H = len(rows)
    W = max(len(r) for r in rows)
    g = ''.join(r.ljust(W, '#') for r in rows).encode()
    s = g.find(b'S')
    e = g.find(b'E')
    if s < 0 or e < 0:
        return -1
    N = H * W
    seen = bytearray(N)
    wall = ord('#')
    seen[s] = 1
    cur = [s]
    d = 0
    while cur:
        for p in cur:
            if p == e:
                return d
        nxt = []
        for p in cur:
            c = p % W
            if c > 0:
                q = p - 1
                if not seen[q] and g[q] != wall:
                    seen[q] = 1
                    nxt.append(q)
            if c < W - 1:
                q = p + 1
                if not seen[q] and g[q] != wall:
                    seen[q] = 1
                    nxt.append(q)
            if p >= W:
                q = p - W
                if not seen[q] and g[q] != wall:
                    seen[q] = 1
                    nxt.append(q)
            if p + W < N:
                q = p + W
                if not seen[q] and g[q] != wall:
                    seen[q] = 1
                    nxt.append(q)
        cur = nxt
        d += 1
    return -1


def main():
    print(solve(sys.stdin.read()))


if __name__ == '__main__':
    main()
